object ReadingComprehensionData {
    val stories = listOf(
        // ===== 1 КЛАСС =====
        ComprehensionStory("1_1", 1, "Капли на окне", "За окном шёл дождь. Ира сидела дома и смотрела на стекло. Маленькие капли стояли на месте, а большие медленно ползли вниз.\nДве капли рядом с рамой соединились. Получилась одна большая капля. Она быстро скатилась к нижнему краю окна. Ира нарисовала её путь в тетради. Когда дождь кончился, девочка показала свой рисунок папе и рассказала о каплях.", listOf("Какая погода была за окном?", "Какие капли медленно ползли вниз?", "Что случилось с двумя каплями у рамы?", "Кому Ира показала рисунок?")),
        ComprehensionStory("1_2", 1, "Сапоги у двери", "Костя вернулся с прогулки и снял мокрые сапоги. Он оставил один у двери, а второй под стулом. Утром мальчик собрался гулять и сразу нашёл только один сапог.\nКостя вспомнил вчерашний вечер и заглянул под стул. Второй сапог стоял там. После новой прогулки мальчик поставил оба сапога рядом у двери. Теперь они ждали следующего выхода вместе.", listOf("Какими были сапоги после прогулки?", "Где стоял второй сапог?", "Что помогло Косте его найти?", "Как мальчик поставил сапоги после новой прогулки?")),
        ComprehensionStory("1_3", 1, "Тарелка для друзей", "К Оле пришли две подруги. Мама вымыла яблоки и разрезала их на дольки. Оля стала раскладывать угощение на три маленькие тарелки.\nНа первой тарелке было много долек, а на последней всего две. Девочка переложила несколько кусочков, чтобы всем досталось поровну. Потом она поставила тарелки на стол. Подруги сели рядом, и Оля принесла салфетки.", listOf("Сколько подруг пришло к Оле?", "Кто разрезал яблоки?", "Почему Оля переложила несколько долек?", "Что девочка принесла после тарелок?")),
        ComprehensionStory("1_4", 1, "Низкий стол", "Тимур строил башню из кубиков на ковре. Младшая сестра подошла и задела её ногой. Башня рассыпалась. Сестра огорчилась и стала собирать кубики.\nТимур предложил строить новую башню на низком столе. Он положил внизу широкие кубики, а сестра принесла маленькие. Теперь они работали вместе. Готовая башня стояла выше ковра, и проходить рядом с ней стало удобнее.", listOf("Где Тимур строил первую башню?", "Почему она рассыпалась?", "Куда перенесли новую башню?", "Какие кубики приносила сестра?")),
        ComprehensionStory("1_5", 1, "Записка на столе", "Утром Сева увидел на столе записку. Мама написала: «Твой шарф лежит на полке». Мальчик прочитал слова и нашёл шарф рядом с шапкой.\nПеред уходом он тоже взял лист бумаги. Сева написал маме: «Спасибо». Потом положил свою записку на то же место. Когда мама вернулась в комнату, она прочитала короткое слово и улыбнулась сыну.", listOf("Кто оставил первую записку?", "Где лежал шарф?", "Какое слово написал Сева?", "Куда мальчик положил свою записку?")),
        ComprehensionStory("1_6", 1, "Мяч под скамейкой", "На площадке Женя катала мяч подруге. Один раз мяч покатился в сторону и остановился под скамейкой. Женя присела, но рукой до него не достала.\nПодруга обошла скамейку с другой стороны. Там мяч лежал совсем близко к краю. Она подняла его и вернула Жене. Девочки выбрали для игры место подальше от скамейки и снова стали катать мяч друг другу.", listOf("Где остановился мяч?", "Почему Женя не взяла его сразу?", "Как подруга смогла взять мяч?", "Какое место девочки выбрали для новой игры?")),
        ComprehensionStory("1_7", 1, "Лодочка", "После дождя у дома была лужа. Миша сделал лодочку из бумаги. Он пустил её на воду. Ветер дул, и лодочка плыла к траве.\nУ края лужи лежала ветка. Лодочка упёрлась в неё и встала. Миша убрал ветку. Лодочка снова поплыла. Мальчик позвал сестру. Теперь они вместе смотрели на маленький белый парус.", listOf("Из чего Миша сделал лодочку?", "Почему лодочка остановилась?", "Что сделал Миша, чтобы лодочка поплыла снова?", "Кого мальчик позвал к луже?")),
        ComprehensionStory("1_8", 1, "Тёплое место", "Кот Рыжик спал на ковре. Утром солнце светило прямо на его лапы. Потом тень от стола закрыла ковёр. Рыжик открыл глаза и встал.\nОн прошёл к окну. Там на полу было светлое пятно. Кот лёг в него и вытянул лапы. Аня тихо поставила рядом миску с водой. Она не стала звать кота: Рыжик уже снова спал.", listOf("Как звали кота?", "Где кот спал в начале рассказа?", "Почему кот перешёл к окну?", "Что Аня поставила рядом с котом?")),
        ComprehensionStory("1_9", 1, "Два семечка", "Лена посадила два семечка в горшок. Она полила землю и поставила горшок на окно. Каждый день девочка смотрела, нет ли ростка.\nСначала земля была пустой. Потом из неё показался зелёный листок. На другой день рядом вырос второй. Лена нарисовала оба ростка в тетради. Теперь у неё была не только маленькая грядка, но и её первый рисунок.", listOf("Сколько семечек посадила Лена?", "Куда девочка поставила горшок?", "Все ли ростки появились в один день?", "Где Лена нарисовала ростки?")),
        ComprehensionStory("1_10", 1, "Синяя пуговица", "У мамы с пальто оторвалась синяя пуговица. Она упала на пол и куда-то укатилась. Мама посмотрела под столом, но там ничего не было.\nКоля принёс фонарик и посветил под кресло. В углу блеснул синий кружок. Мальчик достал пуговицу и отдал маме. Мама пришила её на место. Теперь пальто снова можно было застегнуть.", listOf("Какого цвета была пуговица?", "Где Коля нашёл пуговицу?", "Что помогло мальчику её увидеть?", "Что мама сделала с найденной пуговицей?")),
        ComprehensionStory("1_11", 1, "Чашка с кораблём", "У Тани была чашка с кораблём. У брата была чашка с полосками. После завтрака папа вымыл посуду и поставил обе чашки на полку.\nТаня захотела попить. Она взяла чашку с полосками, но заметила, что это чашка брата. Девочка вернула её на полку и нашла свою. Корабль на боку помог Тане не перепутать посуду.", listOf("Что было нарисовано на чашке Тани?", "Кто вымыл чашки после завтрака?", "Чью чашку Таня взяла сначала?", "Что помогло девочке найти свою чашку?")),
        ComprehensionStory("1_12", 1, "Дорожка в снегу", "Ночью выпал снег. Утром дорожка от дома до калитки стала белой. Папа взял большую лопату, а Дима принёс маленькую.\nПапа убирал снег с дорожки. Дима очищал место у калитки. Когда они закончили, бабушка вышла из дома с сумкой. Она прошла по чистой дорожке и помахала им рукой. Дима поставил свою лопату рядом с папиной.", listOf("Что произошло ночью?", "Какую лопату принёс Дима?", "Где мальчик убирал снег?", "Кто прошёл по очищенной дорожке?")),
        ComprehensionStory("1_13", 1, "Дом для зайца", "У Сони был маленький игрушечный заяц. Девочка решила сделать ему дом. Она взяла пустую коробку и положила на дно мягкую ткань.\nНо заяц не помещался в коробке: его длинные уши торчали наружу. Соня нашла коробку побольше и перенесла туда ткань. Теперь заяц лежал удобно. Девочка поставила его новый дом рядом со своей кроватью.", listOf("Для кого Соня делала дом?", "Что девочка положила на дно коробки?", "Почему первая коробка не подошла?", "Где Соня поставила новый дом?")),
        ComprehensionStory("1_14", 1, "Шарф для снеговика", "Во дворе Маша и папа слепили снеговика. Папа сделал ему нос из морковки. Маша принесла старый красный шарф и обмотала его вокруг снежной шеи.\nШарф был длинным. Один конец лежал на снегу. Маша завязала его ещё раз. Теперь оба конца висели над землёй. Снеговик стоял у ворот и словно встречал всех, кто входил во двор.", listOf("Из чего был сделан нос снеговика?", "Какого цвета был шарф?", "Почему Маша завязала шарф ещё раз?", "Где стоял снеговик?")),
        ComprehensionStory("1_15", 1, "Зелёный флажок", "Ваня и Лёва играли в гонки машинок. Лёва поставил машины у линии старта. Ваня взял зелёный флажок. Они решили начинать гонку, когда флажок поднимется.\nСначала Ваня поправил колесо своей машины. Лёва спокойно ждал. Потом Ваня поднял флажок, и обе машинки покатились вперёд. На следующую гонку ребята поменялись местами: теперь флажок держал Лёва.", listOf("Во что играли мальчики?", "Какого цвета был флажок?", "Почему Лёва сначала ждал?", "Кто держал флажок на следующей гонке?")),
        ComprehensionStory("1_16", 1, "Чистая кисть", "Аня рисовала зелёную траву. Потом она захотела нарисовать голубое небо. Девочка набрала синюю краску, но на бумаге получилась зелёная полоса.\nМама заметила, что на кисти осталась краска от травы. Аня промыла кисть в воде и взяла чистый лист. Теперь небо вышло голубым. Первый рисунок девочка тоже оставила: на нём можно было дорисовать большой зелёный куст.", listOf("Что Аня рисовала сначала?", "Почему на бумаге появилась зелёная полоса?", "Что Аня сделала перед новым рисунком?", "Что можно было дорисовать на первом листе?")),
        ComprehensionStory("1_17", 1, "Короткий карандаш", "У Пети сломался кончик карандаша. Он поточил его, но карандаш стал совсем коротким. Пете было трудно держать его в руке.\nДедушка достал из ящика специальный держатель. Он вставил в него короткий карандаш. Теперь карандаш снова было удобно брать. Петя дорисовал крышу своего домика и показал рисунок дедушке. Короткий карандаш ещё мог послужить мальчику.", listOf("Что сломалось у карандаша?", "Почему Пете стало трудно рисовать?", "Что достал дедушка из ящика?", "Что Петя дорисовал на рисунке?")),
        ComprehensionStory("1_18", 1, "Ключ на ленте", "Мама искала ключ от маленького ящика. Раньше он лежал возле зеркала. Теперь на этом месте стояла ваза с цветами.\nЛиза вспомнила, что утром мама убирала стол. Девочка посмотрела в коробочку у окна. Там лежал ключ с жёлтой лентой. Лиза принесла его маме. Мама открыла ящик и достала старые фотографии. Они вместе стали рассматривать снимки.", listOf("Что искала мама?", "Что стояло на прежнем месте ключа?", "Где Лиза нашла ключ?", "Что мама достала из ящика?")),
        ComprehensionStory("1_19", 1, "Книжка для куклы", "Нина сложила лист бумаги пополам. Получилась маленькая книжка. На первой странице она нарисовала дом, на второй — сад, а на третьей — кота.\nДевочка посадила куклу на стул и стала показывать ей рисунки. Брат попросил тоже посмотреть книжку. Нина придвинула второй стул. Теперь у её маленькой книжки было два слушателя. Брат придумал имя для нарисованного кота.", listOf("Как Нина сделала книжку?", "Что было нарисовано на второй странице?", "Зачем Нина придвинула второй стул?", "Что придумал брат?")),
        ComprehensionStory("1_20", 1, "За окном автобуса", "Мила ехала с папой в автобусе. Она села у окна и смотрела на улицу. Сначала мимо проплыл парк, потом большой магазин.\nУ магазина девочка заметила человека с красной сумкой. Вскоре автобус остановился. Человек вошёл и сел впереди. Мила тихо сказала папе, что уже видела эту сумку. До дома они проехали ещё две остановки и вышли вместе.", listOf("С кем Мила ехала в автобусе?", "Что она увидела сначала: парк или магазин?", "Какого цвета была сумка у человека?", "Сколько остановок они проехали после магазина?")),
        ComprehensionStory("1_21", 1, "Полосатый камешек", "На прогулке Саша нашёл гладкий камешек с белой полосой. Он показал находку маме. Мама разрешила взять камешек домой и положить в коробку с коллекцией.\nДома мальчик вымыл находку. На мокром камне белая полоса стала виднее. Саша нарисовал её на листке и положил рисунок рядом. Теперь среди серых камешков было легко найти именно этот.", listOf("Какая полоса была на камешке?", "Куда Саша собирался положить находку?", "Что мальчик сделал с камешком дома?", "Зачем Саша положил рядом рисунок?")),
        ComprehensionStory("1_22", 1, "Билеты в театр", "Даша устроила дома театр кукол. Она нарисовала два билета и поставила перед столом два стула. На спектакль пришли мама и брат.\nБрат хотел сесть ближе к столу, но стулья стояли друг за другом. Даша поставила их рядом, напротив кукол. Теперь всем было хорошо видно сцену. Девочка раздала билеты и начала историю про медведя с зонтом.", listOf("Сколько билетов нарисовала Даша?", "Кто пришёл на спектакль?", "Почему Даша переставила стулья?", "Про кого была история?")),
        ComprehensionStory("1_23", 1, "Три цвета", "Глеб строил поезд из кубиков. Он хотел поставить красные вагоны рядом, но кубики лежали кучей. Мальчик долго искал нужный цвет.\nСестра предложила сначала разложить кубики. Глеб сделал три ряда: красный, синий и жёлтый. Теперь он быстро находил любой кубик. Поезд получился длинным. Для станции мальчик выбрал синие кубики, а для крыши — жёлтые.", listOf("Что строил Глеб?", "Почему мальчик долго искал нужный кубик?", "Сколько рядов сделал Глеб?", "Какого цвета была крыша станции?")),
        ComprehensionStory("1_24", 1, "Тени на стене", "Вечером папа выключил верхний свет и включил фонарик. На стене появилось светлое пятно. Варя подняла ладонь, и в пятне выросла большая тень.\nДевочка подвинула руку ближе к стене. Тень стала меньше. Варя позвала брата. Они по очереди показывали пальцами ушки зайца. Папа держал фонарик, а дети угадывали, чья тень сейчас появилась на стене.", listOf("Что папа включил вместо верхнего света?", "Где появилось светлое пятно?", "Когда тень стала меньше?", "Какое животное дети показывали пальцами?")),
        ComprehensionStory("1_25", 1, "Бумажная цепочка", "Рома делал цепочку из бумажных колец. Он взял красную полоску, согнул её и склеил края. Потом продел в кольцо синюю полоску и тоже склеил её.\nСестра принесла жёлтую бумагу. Вместе они добавили ещё несколько колец. Рома положил цепочку на стол, чтобы клей высох. Потом мама помогла повесить её над дверью. Комната стала нарядной.", listOf("Какого цвета было первое кольцо?", "Что принесла сестра?", "Почему Рома положил цепочку на стол?", "Где повесили готовую цепочку?")),

        // ===== 2 КЛАСС =====
        ComprehensionStory("2_1", 2, "Один большой зонт", "Когда закончились уроки, на улице начался дождь. Оля достала из рюкзака большой жёлтый зонт. У дверей школы стоял её сосед Артём. Свой зонт он оставил дома и теперь ждал, когда дождь станет тише.\nОля предложила идти вместе. До их дома было недалеко, но дорожка проходила мимо большой лужи. Ребята выбрали другой путь, вдоль забора. Артём нёс папку Оли, чтобы ей было удобнее держать зонт.\nДома Оля поставила мокрый зонт сушиться. Мама удивилась, что папка осталась сухой. Девочка рассказала, как они с Артёмом помогли друг другу.", listOf("Почему Артём ждал у дверей школы?", "Почему ребята пошли вдоль забора?", "Как Артём помог Оле?", "Что Оля сделала с зонтом дома?")),
        ComprehensionStory("2_2", 2, "План двора", "Петя хотел показать новому другу Саше свой двор. Он нарисовал план: дом, песочницу, две скамейки и старую яблоню. Яблоню мальчик отметил зелёным кружком.\nНа следующий день Петя заболел и не вышел гулять. Он передал Саше рисунок через маму. Возле зелёного кружка была подпись: «Здесь найдёшь мой сюрприз». Саша посмотрел на план, прошёл мимо песочницы и остановился под яблоней. На нижней ветке висел бумажный конверт.\nВнутри лежала нарисованная открытка с кораблём. Саша принёс домой лист бумаги и тоже сделал открытку. Когда Петя поправился, его уже ждал ответный сюрприз.", listOf("Что обозначал зелёный кружок на плане?", "Почему Петя не вышел гулять?", "Где Саша нашёл конверт?", "Что Саша приготовил для Пети?")),
        ComprehensionStory("2_3", 2, "Свободная скамейка", "В субботу Вера и дедушка пришли в парк. Они хотели посидеть у пруда. На одной скамейке лежали сухие листья, а на другой сидела женщина с маленьким ребёнком. Вера уже собиралась предложить дедушке идти дальше.\nДедушка достал из сумки старую газету и аккуратно смахнул листья с пустой скамейки. Вера помогла ему убрать несколько тонких веток. Скоро место для отдыха было готово. Ребята у пруда смотрели, как утки ныряют, но ничего не бросали в воду.\nВера села рядом с дедушкой. Она поняла, что иногда удобное место можно подготовить самим, а не искать другое.", listOf("Где Вера и дедушка хотели посидеть?", "Почему пустая скамейка сначала была неудобной?", "Чем дедушка смахнул листья?", "Что поняла Вера?")),
        ComprehensionStory("2_4", 2, "Занавес для театра", "В классе готовили кукольный спектакль. Дима принёс двух кукол, а Лиза сделала декорации из картона. Для сцены поставили на стол большую коробку. Всё было готово, кроме занавеса. Лиза принесла кусок синей ткани, но он оказался слишком коротким. Нижний край коробки оставался виден.\nДима предложил закрыть край полоской зелёной бумаги. Ребята вырезали из неё траву и прикрепили к сцене. Теперь короткий занавес подходил. Во время спектакля из бумажной травы выглядывал кукольный заяц. Зрители смеялись, а после представления просили показать, как устроена маленькая сцена.", listOf("Что Лиза сделала для спектакля?", "Почему синий занавес сначала не подходил?", "Как ребята закрыли нижний край коробки?", "Что зрители попросили после спектакля?")),
        ComprehensionStory("2_5", 2, "Письмо в конверте", "В воскресенье Марина писала письмо бабушке. Она рассказала о школьном празднике и нарисовала платье, в котором выступала. Мама дала девочке конверт. Марина сложила письмо, но заметила, что рисунок оказался снаружи сгиба. Она боялась помять его, когда будет вкладывать лист.\nМама предложила сначала потренироваться на чистой бумаге такого же размера. Марина попробовала два способа и выбрала тот, при котором рисунок оставался внутри. Затем она аккуратно сложила настоящее письмо. На конверте мама написала адрес, а девочка добавила маленькую звезду возле своего имени. Утром они вместе отнесли письмо на почту.", listOf("О чём Марина рассказала бабушке?", "Почему девочка боялась вкладывать письмо в конверт?", "На чём Марина сначала попробовала складывать письмо?", "Что девочка добавила возле своего имени?")),
        ComprehensionStory("2_6", 2, "Красная варежка", "После прогулки в школьной раздевалке лежала красная варежка. Коля хотел отнести её учительнице, но увидел на краю вышитую букву Н. Он вспомнил, что Нина утром показывала новые варежки. Девочка уже сидела в классе и доставала учебники. Коля подошёл к ней с находкой.\nНина посмотрела на варежку и покачала головой. Её варежки были с белыми полосками, а эта была однотонная. Тогда учительница положила находку на отдельную полку возле входа. После уроков туда подошёл Никита из соседнего класса. На его второй варежке была такая же буква. Он сразу узнал свою потерю.", listOf("Где Коля нашёл варежку?", "Почему Коля сначала подошёл к Нине?", "Чем варежки Нины отличались от найденной?", "Кто забрал находку после уроков?")),
        ComprehensionStory("2_7", 2, "Подпись под фотографией", "Мама достала старый альбом и показала Соне фотографию. На ней маленькая девочка держала огромный букет. Соня решила, что это мама в первый день школы. Но мама засмеялась: на снимке была тётя Ира. В детстве сёстры были очень похожи. Под фотографией не оказалось подписи.\nСоня предложила подписать снимки, пока мама помнит, кто на них изображён. Они взяли полоски бумаги и начали с этой фотографии. Мама назвала место и год, а Соня записала имя тёти. К вечеру в альбоме появились аккуратные подписи. Одну фотографию отложили: мама хотела сначала спросить о ней у бабушки.", listOf("Кого Соня сначала узнала на фотографии?", "Почему девочка перепутала маму и тётю?", "Что Соня предложила сделать со снимками?", "Почему одну фотографию отложили?")),
        ComprehensionStory("2_8", 2, "Лёгкий рюкзак", "Перед экскурсией Антон собрал рюкзак. Он положил туда воду, блокнот, карандаш, три машинки и толстую книгу. Когда мальчик надел рюкзак, лямки сильно потянули плечи. Антон решил взять большую сумку, но папа предложил посмотреть, что понадобится в музее. Вместе они прочитали памятку от учительницы.\nМашинки остались дома, а книгу Антон положил возле кровати, чтобы читать вечером. В рюкзаке освободилось место для лёгкой куртки. На экскурсии мальчик записывал названия старинных предметов и зарисовал узор на чашке. Когда класс вернулся, Антон достал блокнот и показал папе рисунок. Рюкзак он всю дорогу нёс сам.", listOf("Почему Антону было неудобно нести рюкзак?", "Что папа предложил сделать перед сменой сумки?", "Для чего освободилось место в рюкзаке?", "Какой рисунок Антон показал папе?")),
        ComprehensionStory("2_9", 2, "Синяя лента", "На уроке физкультуры две команды готовились к эстафете. Игроки должны были передавать друг другу мягкое кольцо. У команды Вики все стояли рядом и спорили, кто побежит первым. Пока ребята спорили, кольцо несколько раз переходило из рук в руки. Учитель попросил команду выстроиться по порядку.\nВика предложила положить синюю ленту возле первого игрока. Теперь всем было видно, откуда начинается очередь. Ребята договорились о порядке и заняли места. После каждого круга бегун передавал кольцо следующему товарищу и уходил в конец ряда. Когда эстафета закончилась, Вика свернула ленту и вернула её учителю.", listOf("Что игроки передавали друг другу?", "О чём сначала спорили ребята?", "Зачем Вика положила синюю ленту возле первого игрока?", "Куда уходил бегун после передачи кольца?")),
        ComprehensionStory("2_10", 2, "Два бумажных пакета", "Саша с мамой зашли в пекарню. Они купили булочки для домашнего чаепития и два рогалика для дедушки. Продавец положил покупки в одинаковые бумажные пакеты. По дороге мама вспомнила, что дома трудно будет отличить один пакет от другого, не раскрывая их. Саша достал из кармана карандаш.\nНа пакете с рогаликами он нарисовал очки, потому что дедушка всегда надевал очки для чтения. На другом пакете появилась чашка. Дома мама сразу поставила булочки на стол, а рогалики оставила для дедушки. Когда он пришёл, Саша подал ему пакет с рисунком. Дедушка улыбнулся и положил свои настоящие очки рядом.", listOf("Что купили для дедушки?", "Почему мама могла перепутать пакеты?", "Что Саша нарисовал на пакете с рогаликами?", "Что мама сначала поставила на стол дома?")),
        ComprehensionStory("2_11", 2, "Узор в прихожей", "У бабушки в прихожей лежали квадратные плитки двух цветов. Ваня заметил, что белая плитка всегда соседствует с серой. Пока бабушка разговаривала с мамой, мальчик решил нарисовать этот узор. Он начертил в блокноте квадраты и стал закрашивать их простым карандашом. В середине рисунка появились два серых квадрата подряд.\nВаня сравнил рисунок с полом и нашёл место, где сбился. Он стёр один квадрат и продолжил работу, каждый раз проверяя соседнюю клетку. Потом бабушка принесла цветные карандаши. Ваня сделал второй узор, уже из жёлтых и зелёных квадратов. Этот рисунок он оставил бабушке, а первый забрал домой.", listOf("Каких цветов были плитки в прихожей?", "Какую ошибку Ваня заметил в своём рисунке?", "Как мальчик нашёл место ошибки?", "Какой рисунок Ваня оставил бабушке?")),
        ComprehensionStory("2_12", 2, "Кто сегодня дежурит", "В классе дежурные каждый день менялись. В понедельник Егор приготовил доску, хотя его очередь была только во вторник. Он перепутал дни в списке на стене. Учительница поблагодарила его за помощь и предложила сделать список понятнее. Егор посмотрел на длинный столбик фамилий и задумался.\nПосле уроков он нарисовал рядом с каждой датой маленькое окошко. В окошко текущего дня вставили красный бумажный кружок. Утром кружок передвигали ниже. Теперь Егор сразу видел, какая строчка нужна. Во вторник он снова подготовил доску, а Маша расставила книги на полке. На этот раз оба дежурных вовремя заняли свои места.", listOf("Когда была очередь Егора дежурить?", "Почему Егор приготовил доску в понедельник?", "Как в списке отмечали текущий день?", "Что делала Маша во вторник?")),
        ComprehensionStory("2_13", 2, "Ворота для машины", "Лёня строил из кубиков гараж для игрушечной машины. Он поставил две стенки, а сверху положил длинную деталь. Гараж получился красивым, но машина не проходила в ворота. Мальчик поднял деталь выше и попробовал снова. Теперь крыша не мешала, зато колёса застревали между стенками. Лёня позвал сестру посмотреть на постройку.\nСестра предложила поставить машину перед воротами и сравнить её ширину с проёмом. Лёня раздвинул стенки на один кубик. Машина легко въехала внутрь. Возле гаража ребята устроили стоянку и положили маленькую табличку. На ней Лёня написал название своей машины. До ужина он успел построить ещё один гараж для автобуса.", listOf("Из чего Лёня строил гараж?", "Что мешало машине после того, как крышу подняли?", "Что Лёня сделал после совета сестры?", "Для какой игрушки он построил второй гараж?")),
        ComprehensionStory("2_14", 2, "Тихий звон", "На музыкальном занятии дети разучивали песню. У каждого был небольшой инструмент: бубен, колокольчик или деревянные ложки. Настя получила колокольчик. Когда все начали играть сразу, его звон почти не слышался. Девочка решила встряхивать колокольчик сильнее, но песня стала ещё громче. Учитель остановил ребят и предложил послушать инструменты по очереди.\nСначала прозвучал бубен, потом ложки, а последним звенел колокольчик. Дети заметили его лёгкий звук. В песне учитель оставил для Насти короткую паузу, когда остальные молчали. Девочка сыграла всего три раза, и звон услышал весь класс. После занятия Настя осторожно положила колокольчик в коробку.", listOf("Какой инструмент получила Настя?", "Почему сначала его звон почти не слышался?", "Какой инструмент прозвучал первым при игре по очереди?", "Что помогло всему классу услышать колокольчик?")),
        ComprehensionStory("2_15", 2, "Корабль на открытке", "В музее Арсений долго рассматривал модель старого корабля. Ему понравились белые паруса и маленькие окна на корме. После экскурсии класс подошёл к стойке с открытками. Мальчик выбрал открытку с похожим кораблём, но на рисунке было гораздо больше парусов. Арсений вернулся к модели вместе с учительницей.\nОн сравнил корабли и увидел, что у них разные названия. Открытка изображала другой корабль. Тогда мальчик попросил продавца найти открытку именно с той моделью, которую он рассматривал. Такая открытка нашлась на нижней полке. Дома Арсений показал её маме и рассказал, какие детали запомнил во время экскурсии.", listOf("Какие детали модели понравились Арсению?", "Почему мальчик вернулся к модели?", "Что Арсений узнал, сравнив названия?", "Где нашлась нужная открытка?")),
        ComprehensionStory("2_16", 2, "Шарф для мишки", "У Маши был игрушечный мишка в синей куртке. Девочка захотела сделать ему шарф и попросила у бабушки полоску мягкой ткани. Она выбрала самый длинный кусок и обернула его вокруг шеи игрушки. Концы шарфа лежали на полу. Когда Маша поставила мишку на игрушечный стул, ткань закрыла его лапы.\nБабушка предложила сначала примерить бумажную полоску. Маша сложила её пополам и отметила, где должны заканчиваться концы. Бабушка по этой мерке укоротила ткань. Новый шарф доходил мишке до пояса. Девочка нарисовала его в блокноте, а лишний кусочек ткани положила в коробку для будущих поделок.", listOf("Во что был одет игрушечный мишка?", "Почему первый шарф был неудобным?", "Из чего Маша сделала мерку для шарфа?", "Куда девочка положила лишний кусочек ткани?")),
        ComprehensionStory("2_17", 2, "Партия после обеда", "Павел играл с дедушкой в шахматы. До обеда они не успели закончить партию. Мама попросила освободить стол, чтобы поставить тарелки. Павел огорчился: ему хотелось продолжить игру позже. Дедушка предложил записать, где стоят фигуры. Мальчик принёс блокнот и нарисовал квадратную доску с клетками.\nОни вместе отметили на рисунке все фигуры. Возле рисунка Павел написал, кто должен ходить следующим. Потом шахматы убрали в коробку. После обеда дедушка достал доску, а мальчик расставил фигуры по своей записи. Один белый конь оказался не на той клетке. Дедушка заметил ошибку, и Павел исправил её перед следующим ходом.", listOf("Почему шахматы пришлось убрать со стола?", "Как дедушка предложил сохранить незавершённую партию?", "Что Павел написал возле рисунка доски?", "Какую ошибку исправили перед продолжением игры?")),
        ComprehensionStory("2_18", 2, "Шапка снеговика", "Во дворе школы дети слепили снеговика. Вместо шапки они надели ему лёгкое пластиковое ведёрко. Когда подул ветер, ведёрко упало рядом. Дети снова поставили его на голову, но оно держалось плохо. Учительница предложила придумать другую шапку из снега. Ребята принесли несколько небольших снежных комков.\nАлина положила один комок сверху и осторожно придала ему круглую форму. По краю ребята добавили тонкий снежный валик. Получилась шапка с широкими полями. Ведёрко теперь стояло возле снеговика, будто корзина. После уроков Алина показала маме свою работу. Мама сразу заметила необычную шапку и попросила дочь встать рядом для фотографии.", listOf("Что сначала служило снеговику шапкой?", "Почему дети решили сделать другую шапку?", "Из чего сделали новую шапку?", "Зачем мама попросила Алину встать рядом со снеговиком?")),
        ComprehensionStory("2_19", 2, "Записка на двери", "В четверг Тимур пришёл на занятие кружка рисования. На привычной двери висела записка: сегодня кружок занимается в кабинете напротив библиотеки. Мальчик прочитал только первую строчку и решил, что занятие отменили. Он уже собирался уйти, когда из библиотеки вышла знакомая девочка с папкой. Тимур рассказал ей о записке.\nДевочка предложила дочитать её до конца. Вместе они нашли нужный кабинет. Там уже лежали листы бумаги и цветные мелки. Руководитель объяснила, что в обычном кабинете меняют шкафы, поэтому группа временно переехала. Тимур сел возле окна и нарисовал библиотечную дверь. На его рисунке была большая записка с тремя строчками.", listOf("На какой кружок пришёл Тимур?", "Почему мальчик решил, что занятие отменили?", "Где в этот день проходило занятие?", "Почему группа временно сменила кабинет?")),
        ComprehensionStory("2_20", 2, "Деталь с облаком", "Катя и её брат собирали большую картинку из деталей. На картинке были дом, сад и голубое небо. Дом уже стоял на своём месте, а в небе оставалось пустое окошко. Катя долго искала нужную деталь среди кусочков с травой. Брат заметил на коробке белое облако как раз над крышей.\nРебята стали искать деталь с белым краем. Она нашлась под крышкой коробки. Катя вставила её в окошко, но кусочек не подошёл. Девочка повернула его другой стороной, и облако встало на место. Они закончили картинку перед ужином. Разбирать её сразу не стали: брат хотел утром показать готовый сад папе.", listOf("Какая часть картинки уже была собрана?", "Что помогло ребятам понять, какую деталь искать?", "Где нашлась деталь с облаком?", "Почему картинку не разобрали сразу?")),
        ComprehensionStory("2_21", 2, "Карточки с именами", "В класс пришёл новый ученик Борис. На первом занятии ребята работали в группах. Борису дали место за столом с четырьмя одноклассниками, но он ещё не знал их имён. Когда понадобился зелёный карандаш, мальчик молча показал на чужой пенал. Оля поняла просьбу и протянула карандаш, а затем назвала себя.\nОна предложила всем написать имена на маленьких карточках. Карточки сложили уголком и поставили перед каждым. Теперь Борис мог обращаться к ребятам по имени. Вместе они нарисовали большой лес. В конце занятия мальчик помог собрать карандаши и уже без карточки позвал Олю посмотреть на готовый рисунок.", listOf("Почему Борис сначала молча показал на пенал?", "Какой карандаш понадобился мальчику?", "Что Оля предложила написать на карточках?", "Что нарисовала группа?")),
        ComprehensionStory("2_22", 2, "Две одинаковые кошки", "В коридоре школы устроили выставку детских рисунков. Полина нарисовала серую кошку возле окна. Рядом повесили почти такую же кошку, но на зелёном ковре. Под обоими рисунками лежали карточки с именами. На следующий день Полина увидела, что её имя оказалось под чужой работой. Видимо, карточки передвинули, когда вытирали полку.\nДевочка позвала учительницу и показала свою кошку возле окна. Вместе они вернули подписи на места. Учительница предложила прикрепить каждую карточку прямо к листу. Полина помогла подготовить полоски липкой ленты. После уроков мама пришла посмотреть выставку и сразу нашла рисунок дочери по аккуратной подписи внизу.", listOf("Где Полина нарисовала кошку?", "Что Полина заметила на следующий день?", "Как решили закрепить подписи после исправления?", "Как мама нашла рисунок дочери?")),
        ComprehensionStory("2_23", 2, "Место для гостя", "В субботу Даня помогал накрывать стол к завтраку. Он поставил четыре тарелки: для себя, сестры, мамы и папы. Когда всё было готово, мама сказала, что скоро придёт бабушка. Даня достал ещё одну тарелку и поставил её на край стола. Но там уже стояла большая корзинка с хлебом.\nМальчик попробовал подвинуть тарелки, однако места всё равно не хватало. Сестра предложила разложить хлеб на две маленькие тарелочки. Корзинку убрали, и бабушкина тарелка удобно поместилась между чашками. Даня принёс ещё один стул. Когда бабушка вошла, на её месте лежала салфетка с маленьким рисунком, который Даня сделал заранее.", listOf("Сколько тарелок Даня поставил сначала?", "Почему понадобилась ещё одна тарелка?", "Что предложила сестра, чтобы освободить место?", "Что лежало на бабушкином месте?")),
        ComprehensionStory("2_24", 2, "Чтение по ролям", "На уроке дети читали рассказ по ролям. Свете досталась роль девочки, а Роме роль старого садовника. Рома говорил так тихо, что ребята на последних партах не слышали слов. Он хотел читать громче, но торопился и пропускал окончания. Учительница предложила ему сначала прочитать одну реплику медленно и спокойно.\nРома сделал вдох и попробовал снова. Теперь слова было хорошо слышно. Света дождалась конца его реплики и только потом начала свою. На этот раз разговор героев получился ровным. После чтения учительница спросила, кто хочет поменяться ролями. Рома выбрал слова рассказчика, а роль садовника передал соседу по парте.", listOf("Какую роль получил Рома сначала?", "Почему ребята на последних партах не слышали его?", "Что учительница предложила Роме?", "Какую роль Рома выбрал после чтения?")),
        ComprehensionStory("2_25", 2, "Ракушки в коробке", "После поездки к морю Яна привезла коробку ракушек. Она хотела показать их классу и рассказать, где нашла каждую. В большой коробке ракушки перекатывались и стучали друг о друга. Яна вспомнила, что дома есть маленькие коробочки от подарков. Она достала четыре коробочки и поставила их рядом на столе.\nВ первую девочка положила гладкие ракушки, во вторую полосатые, а в третью самые маленькие. Четвёртую оставила пустой. На крышках она нарисовала такие же узоры. Коробочки плотно вошли в большую коробку. В школе Яна открывала их по очереди. Ребята рассматривали находки, а одну пустую коробочку попросили оставить для классной коллекции камешков.", listOf("Откуда Яна привезла ракушки?", "Почему она решила использовать маленькие коробочки?", "Какие ракушки Яна положила во вторую коробочку?", "Для чего ребята попросили пустую коробочку?")),

        // ===== 3 КЛАСС =====
        ComprehensionStory("3_1", 3, "Утренний маршрут", "Никита каждый день ходил в школу одной дорогой. Однажды учительница попросила детей заметить по пути что-нибудь новое. Мальчик решил, что ничего интересного не найдёт: он знал каждую скамейку возле своего дома.\nУтром Никита вышел немного раньше. У соседнего подъезда он увидел мокрые следы на сухом асфальте. Они вели к клумбе. Рядом стояла женщина с пустой лейкой. Мальчик понял, откуда появились следы. Чуть дальше он заметил, что на дереве у ворот появились первые жёлтые листья. Вчера Никита прошёл мимо и не посмотрел наверх.\nВ классе мальчик рассказал о своих находках. Оказалось, другие дети тоже увидели много небольших перемен. Теперь привычная дорога казалась Никите интереснее. Он решил время от времени выходить пораньше, чтобы спокойно смотреть вокруг.", listOf("Какое задание дала учительница?", "Откуда появились мокрые следы?", "Почему Никита не заметил жёлтые листья накануне?", "Как изменилось отношение Никиты к привычной дороге?")),
        ComprehensionStory("3_2", 3, "Книжная закладка", "В школьной библиотеке Даша выбрала книгу о путешествиях. Между страницами лежала полоска картона с рисунком гор. На обороте было написано: «Вернись к этому месту — здесь начинается самое интересное». Подписи не было.\nДаша захотела сразу открыть отмеченную страницу, но библиотекарь предложила начать с первой главы. Девочка согласилась и вечером принялась читать. Когда она добралась до закладки, герои как раз собирались перейти реку. Теперь Даша знала, почему переход был для них таким важным. Если бы она начала с середины, многое осталось бы непонятным.\nЧерез неделю девочка вернула книгу. Старую закладку она отдала библиотекарю, а рядом положила свою. На ней Даша нарисовала реку и написала: «Читайте сначала. Тогда путешествие станет вашим». Библиотекарь улыбнулась и оставила новую закладку возле стойки для других читателей.", listOf("Что Даша нашла в книге?", "Что предложила библиотекарь?", "Почему Даша поняла важность перехода через реку?", "Какую мысль Даша выразила на своей закладке?")),
        ComprehensionStory("3_3", 3, "Первый пас", "Илья впервые пришёл на занятие футбольного кружка. Ребята уже знали друг друга и быстро передавали мяч. Мальчик бегал за ними, но почти не участвовал в игре. К перерыву он решил, что в команде его не замечают, и сел на скамейку рядом с тренером.\nТренер предложил посмотреть на игру со стороны. Илья увидел, что часто оказывался за другими игроками, поэтому товарищи не могли передать ему мяч. Мальчик выбрал свободное место возле края площадки и попросил тренера показать, как сообщить команде, что он готов получить передачу.\nПосле перерыва Илья вернулся на площадку. Он отбежал в сторону, поднял руку и позвал товарища по имени. Мяч покатился к нему. Илья сразу передал его дальше, а потом снова нашёл свободное место. Когда занятие закончилось, ребята пригласили мальчика на следующую тренировку. По дороге домой он рассказал папе о своём первом пасе.", listOf("Почему Илья сначала решил, что его не замечают?", "Почему товарищи не могли передать Илье мяч?", "Как Илья сообщил, что готов получить передачу?", "Что помогло Илье включиться в игру после перерыва?")),
        ComprehensionStory("3_4", 3, "Костюм облака", "К празднику осени Коля должен был изображать облако. Мама нашла белую рубашку, а мальчик приготовил широкую картонную шляпу. На репетиции оказалось, что шляпа закрывает лицо соседнего участника. Стоило Коле повернуться, как сосед отступал и забывал свои слова. Коля расстроился: он целый вечер вырезал округлые края.\nРуководительница предложила примерить костюм перед зеркалом вместе с соседом. Тогда мальчик заметил, сколько места занимает его облако. Мама помогла ему сделать небольшие белые накладки на плечи, а шляпу они оставили дома.\nНа следующей репетиции Коля свободно двигался и никому не мешал. Старую шляпу он всё же принёс в школу. Её прикрепили над нарисованным лесом, и облако стало частью декорации. Когда гости вошли в зал, Коля показал маме знакомые округлые края. Теперь его работа была видна со всех рядов.", listOf("Почему широкая шляпа мешала выступлению?", "Где Коля заметил размеры своего облака?", "Чем заменили шляпу в костюме?", "Как использовали старую шляпу?")),
        ComprehensionStory("3_5", 3, "Обратная дорога", "На прогулке по парку Вера предложила папе запомнить дорогу к маленькому пруду. Она заметила раздвоенную берёзу возле поворота и широкую сосну напротив. По дороге туда девочка уверенно повторяла свои приметы. Папа шёл рядом и слушал, а возле пруда они остановились посмотреть на воду.\nКогда они пошли обратно, Вера сначала не узнала нужный поворот. Раздвоенная берёза теперь стояла с другой стороны дорожки, а сосну закрывал куст. Папа предложил остановиться и осмотреть знакомое место с разных сторон. Девочка подошла к повороту вместе с ним и наконец увидела обе приметы.\nВера вспомнила, что смотрела на деревья только по пути к пруду. На обратной дороге они выглядели иначе. До выхода из парка девочка несколько раз оборачивалась, сравнивая вид вперёд и назад. Дома она рассказала маме, почему сначала растерялась. В следующий раз Вера хотела показать ей берёзу с двух сторон.", listOf("Какие деревья Вера запомнила возле поворота?", "Почему сосну не было сразу видно на обратной дороге?", "Что папа предложил сделать, когда Вера растерялась?", "Зачем Вера оборачивалась по дороге к выходу?")),
        ComprehensionStory("3_6", 3, "Мост для игрушек", "На занятии ребятам предложили построить мост из бумаги. У каждой группы были два листа и несколько игрушечных машин. Сначала команда Сони положила ровный лист между двумя стопками книг. Под тяжёлой машинкой бумага сразу прогнулась.\nСоня предложила взять второй лист и сложить его гармошкой. Ребята положили гармошку на те же опоры, а сверху устроили ровную дорожку из первого листа. Теперь мост выдержал маленькую машину. Но когда дети поставили на него ещё две, середина снова опустилась.\nКоманда придвинула стопки книг друг к другу и повторила опыт. Машины остались на месте. Ребята записали, что изменили: форму бумаги и расстояние между опорами. В конце занятия Соня сказала, что неудачная первая попытка оказалась полезной. Без неё они не стали бы искать другие способы и сравнивать результаты.", listOf("Почему первый мост не выдержал машину?", "Что ребята сделали со вторым листом?", "Что изменили после второй неудачной попытки?", "Почему Соня назвала первую неудачу полезной?")),
        ComprehensionStory("3_7", 3, "До первого ростка", "Учительница предложила классу подготовить фасоль для наблюдения. Каждый должен был выбрать три семени и зарисовать их до посадки. Рита нарисовала три одинаковых овала. Ей хотелось скорее увидеть ростки, а семена казались неинтересными. Она уже собиралась закрыть тетрадь и убрать её в портфель.\nСоседка предложила поменяться рисунками и найти по ним выбранные семена среди остальных. Рита не смогла узнать свои: на рисунке все были одинаковыми. Тогда девочки рассмотрели фасоль. У одного семени было маленькое пятно, другое оказалось длиннее, третье имело светлую полоску сбоку. Рита добавила эти признаки в рисунок.\nУчительница собрала семена в отдельные стаканчики до следующего занятия. Рита положила рядом свою тетрадь и показала соседке исправленную страницу. Теперь девочка легко находила каждое семя по рисунку. Когда прозвенел звонок, Рита спросила, разрешат ли ей зарисовать фасоль перед посадкой, чтобы потом сравнить первые и более поздние записи.", listOf("Что детям нужно было сделать до посадки фасоли?", "Почему Рита не узнала свои семена по первому рисунку?", "Какие признаки Рита заметила у своих семян?", "Почему Рита захотела сделать ещё один рисунок перед посадкой?")),
        ComprehensionStory("3_8", 3, "Ход для младшего", "Каждую субботу Маша играла с дедушкой в шашки. Однажды к ним присоединился младший брат. Он знал правила, но всё время просил подсказать лучший ход. Маша быстро отвечала за него, а потом удивлялась, почему брат скучает и смотрит в окно.\nДедушка предложил поменяться местами: пусть брат решает сам, а Маша объясняет только незнакомые правила. Мальчик долго рассматривал доску. Он передвинул шашку и сразу потерял её. Маша уже хотела показать ошибку, но дедушка попросил подождать до окончания партии и дать брату продолжить игру.\nПосле партии брат сам указал на опасный ход. Во второй игре он проверял соседние клетки и однажды сумел забрать две шашки подряд. Маша похвалила его находку. Когда пришло время ужинать, брат попросил оставить доску на столе. Он хотел завтра попробовать тот же ход ещё раз, уже без чужих подсказок.", listOf("С кем Маша обычно играла в шашки?", "Что дедушка предложил изменить в игре с братом?", "Когда брат сам указал на опасный ход?", "Что показывает просьба брата оставить доску?")),
        ComprehensionStory("3_9", 3, "Полоска для рамки", "На занятии рисованием дети украшали рамки для фотографий. Саша придумал узор из красных кругов и синих квадратов. Он торопился и сначала нарисовал все круги, а потом стал добавлять квадраты. У края рамки места не осталось, и последний квадрат получился совсем маленьким.\nСаша хотел закрасить весь узор тёмной краской. Соседка Нина предложила сначала проверить рисунок на узкой полоске бумаги. Мальчик отметил одинаковые промежутки и чередовал фигуры. Когда полоска была готова, он приложил её к рамке и увидел, где нужно изменить расстояние между элементами.\nСаша взял новую рамку и перенёс на неё исправленный узор. Красные круги и синие квадраты теперь равномерно шли по всем сторонам. Неудачную рамку он тоже сохранил. На её свободном месте мальчик написал дату, а внутри нарисовал смешного кота. Обе работы он забрал домой, чтобы показать маме свой первый и второй варианты.", listOf("Из каких фигур состоял узор Саши?", "Почему последний квадрат получился маленьким?", "Для чего Саша использовал полоску бумаги?", "Что он нарисовал внутри неудачной рамки?")),
        ComprehensionStory("3_10", 3, "Место для рассказа", "Денис собирал небольшие значки. Когда класс устроил выставку коллекций, он принёс коробку и аккуратно разложил всё по цветам. Жёлтые значки лежали слева, синие справа. Ребята посмотрели на них и быстро пошли к следующему столу. Денису стало обидно: коллекцию он собирал два года.\nУчительница спросила, какой значок для него самый дорогой. Денис показал маленький автобус. Его подарил дедушка после их первой совместной поездки. Затем мальчик рассказал про значок с палаткой и про смешного пингвина. Оказалось, с каждым предметом было связано какое-нибудь событие.\nДенис изменил выставку. Он расположил значки рядом с короткими записками о поездках и подарках. Возле автобуса поставил фотографию с дедушкой. После перемены к его столу вернулись одноклассники. Теперь они задавали вопросы и рассказывали о своих поездках. Денису пришлось достать ещё один стул, потому что разговор затянулся до самого звонка.", listOf("Как Денис сначала расположил значки?", "Почему значок с автобусом был ему дорог?", "Что Денис добавил к значкам?", "Почему одноклассники стали дольше оставаться у стола?")),
        ComprehensionStory("3_11", 3, "Бабушкина тетрадь", "В воскресенье Аня помогала бабушке готовить фруктовый салат. Рецепт лежал в старой тетради, но возле слова «яблоко» виднелось пятно. Аня решила, что нужно одно яблоко. Бабушка посмотрела на большую миску и сказала, что салат предназначен для всей семьи, а не для одного человека.\nОни открыли соседнюю страницу. Там бабушка когда-то записала такой же рецепт для двух гостей. Аня сравнила записи и нашла нужное количество яблок. Пока бабушка готовила фрукты, девочка переписала рецепт на чистый лист. Возле каждого продукта она поставила число, а сверху указала количество порций.\nЗа обедом салата хватило всем. Дядя попросил рецепт, чтобы приготовить такой же дома. Аня принесла свой лист, но сначала спросила, сколько человек будет за столом. Дядя ответил, что только двое. Девочка показала ему запись на соседней странице и объяснила, почему для небольшой семьи лучше выбрать именно этот вариант.", listOf("Что мешало Ане прочитать рецепт?", "Где нашёлся рецепт для двух гостей?", "Что Аня указала сверху чистого листа?", "Почему Аня предложила дяде запись с соседней страницы?")),
        ComprehensionStory("3_12", 3, "Не сразу весело", "В субботу Лена ждала двоюродную сестру. Девочки собирались весь день играть вместе, но утром сестра позвонила: поездку пришлось отложить. Лена убрала настольную игру и села возле окна. Брат начал показывать смешные картинки, надеясь развеселить её, однако девочка отворачивалась и просила оставить её в покое.\nБрат обиделся и пошёл к маме. Она объяснила, что Лена готовилась к встрече и сейчас расстроена. Иногда человеку сначала нужно рассказать о своей неприятности. Мальчик вернулся в комнату, сел рядом и спросил, какую игру Лена хотела показать сестре. Девочка достала коробку и объяснила правила.\nБрат слушал, не перебивая, а потом предложил сыграть одну партию. Лена согласилась, хотя настроение ещё не стало весёлым. Во время игры она рассказала о планах на отложенную встречу. К вечеру девочка сама принесла брату смешные картинки. Они выбрали любимую и придумали к ней разговор двух нарисованных котов.", listOf("Почему Лена расстроилась утром?", "Почему брат показывал Лене смешные картинки?", "О чём брат спросил Лену, вернувшись в комнату?", "Что помогло Лене постепенно вернуться к общению?")),
        ComprehensionStory("3_13", 3, "Конверт для ответа", "Лёня написал двоюродной сестре письмо о школьном празднике. Он рассказал про концерт, рисунки и смешной конкурс. В конце мальчик спросил, как живёт её кот. Мама предложила вложить фотографию класса, и Лёня выбрал снимок, где все стояли возле украшенной сцены после выступления.\nЧерез неделю пришёл ответ. Сестра поблагодарила за фотографию, но написала, что не смогла найти на ней Лёню. Мальчик удивился: он сразу узнавал себя возле края сцены. Мама напомнила, что сестра давно его не видела, а одноклассников не знает и потому нуждается в небольшой подсказке.\nЛёня приготовил копию фотографии. На отдельной бумаге он нарисовал такой же ряд ребят и отметил своё место стрелкой. Рядом написал имена двух друзей, о которых рассказывал в письме. Сестра ответила ещё раз и теперь назвала каждого правильно. А на обороте своего письма нарисовала кота, спящего прямо на её школьной сумке.", listOf("О чём Лёня написал сестре в первом письме?", "Почему сестра не нашла Лёню на фотографии?", "Как Лёня обозначил своё место?", "Что сестра нарисовала в последнем ответе?")),
        ComprehensionStory("3_14", 3, "Стол у окна", "В комнате Артёма стояли письменный стол, шкаф и кресло. Мальчик хотел поставить стол ближе к окну, но боялся, что креслу не останется места. Он попросил папу сразу передвинуть мебель. Папа предложил сначала представить новую комнату на бумаге, чтобы проверить разные варианты.\nОни измерили мебель и нарисовали план. Артём вырезал маленькие прямоугольники, обозначающие стол, шкаф и кресло. На первом варианте кресло закрыло дверь шкафа. На втором оно мешало проходу. Тогда мальчик повернул стол другой стороной и поставил кресло возле стены напротив. На плане появился свободный проход.\nВ субботу папа переставил мебель по выбранному рисунку. Артём проверил, удобно ли открывается шкаф, и сел за стол. Из окна теперь был виден двор, а любимое кресло осталось в комнате. Маленькие бумажные прямоугольники мальчик сложил в конверт и подписал его. Он хотел сохранить удачный план на случай следующей перестановки.", listOf("Куда Артём хотел поставить письменный стол?", "Чему мешало кресло на первом варианте плана?", "Как удалось освободить проход?", "Зачем мальчик сохранил бумажные прямоугольники?")),
        ComprehensionStory("3_15", 3, "Три дела сразу", "После занятия в кружке ребята решили привести комнату в порядок. Сначала все принялись складывать листы бумаги. У стола стало тесно, а кисти оставались в стакане и коробки стояли открытыми. Света заметила, что на одно дело собралась вся группа, хотя вокруг хватало другой работы.\nОна предложила назвать всё, что ещё нужно сделать. В список вошли бумага, кисти и коробки с материалами. Света занялась листами вместе с подругой, двое ребят отнесли кисти к раковине, остальные закрыли коробки и расставили их по полкам. Каждому нашлось дело, и никто больше не толкался возле стола.\nРуководительница вернулась и увидела аккуратные столы. Она спросила, как дети успели так быстро. Света показала список, в котором были зачёркнуты все три пункта. На следующем занятии ребята решили после работы выбирать себе разные дела. Список они оставили возле двери, чтобы его было видно группе.", listOf("Почему возле стола сначала стало тесно?", "Какие три дела вошли в список?", "Чем занялась Света вместе с подругой?", "Почему после составления списка уборка пошла быстрее?")),
        ComprehensionStory("3_16", 3, "Время для гостей", "В субботу к Вике должны были прийти друзья. Девочка составила расписание: сначала настольная игра, потом рисунки, затем чай. Каждому занятию она отвела ровно двадцать минут. Вика даже положила возле стола часы, чтобы внимательно следить за временем и успеть выполнить весь придуманный план.\nИгра оказалась сложнее, чем она ожидала. Когда стрелка дошла до нужного места, друзья только начали понимать правила. Вика предложила убрать фишки, но все попросили закончить партию. Девочка посмотрела на свои записи. Для рисунков она приготовила целую пачку бумаги, хотя друзья больше всего ждали игры.\nВика зачеркнула точные минуты и оставила лишь порядок занятий. Ребята спокойно доиграли, а потом каждый нарисовал любимую фишку. Мама принесла чай, когда картинки уже были готовы. После ухода гостей Вика приклеила рисунки на большой лист. Возле него она написала названия игр, которые друзья предложили попробовать при следующей встрече.", listOf("Сколько времени Вика сначала отвела каждому занятию?", "Почему друзья не хотели убирать фишки?", "Что Вика изменила в расписании?", "Что она записала рядом с рисунками после встречи?")),
        ComprehensionStory("3_17", 3, "Улица на столе", "Миша и Юля строили из коробок улицу для игрушечных машин. Миша сделал высокий магазин, а Юля расставила небольшие дома. Когда они закончили, оказалось, что машины негде оставить: все свободные места занимали клумбы из зелёной бумаги. Ребята начали спорить, чью постройку придётся убрать.\nМладший брат предложил сначала проехать по улице одной машиной. Юля осторожно двигала её вдоль домов, а Миша отмечал тесные места. Они заметили широкий пустой участок за магазином. От дороги туда вёл узкий проход, который закрывала всего одна бумажная клумба. Убирать дома теперь не требовалось.\nДети перенесли клумбу к последнему дому и нарисовали за магазином стоянку. Миша добавил указатель, чтобы машины могли найти поворот. Юля поставила возле стоянки скамейку для маленьких фигурок. Младший брат первым повёз туда свой автобус. Он оставил его между нарисованными линиями и попросил построить рядом остановку для следующей поездки.", listOf("Почему машины негде было оставить?", "Что предложил младший брат перед изменением построек?", "Где ребята устроили стоянку?", "Почему для стоянки не пришлось убирать дома?")),
        ComprehensionStory("3_18", 3, "Подпись к рисунку", "Оля нарисовала для школьной выставки девочку под большим зонтом. Рядом стояла собака, а вокруг были синие капли. Оля подписала работу: «Плохой день». Подруга смотрела на рисунок, затем сказала, что день кажется ей весёлым: девочка улыбается и держит в руке яркий воздушный шар.\nОля объяснила, что сначала хотела изобразить испорченную прогулку. Но во время работы добавила шар, собаку и улыбку. Учительница предложила придумать несколько новых названий и проверить, какое точнее передаёт готовый рисунок. Оля записала три варианта, прочитала их и снова внимательно посмотрела на свою героиню.\nДля выставки девочка выбрала название «Дождь не помешал». На открытии младший ученик остановился возле её работы и рассказал, как однажды гулял с папой под зонтом. Оля показала ему собаку и спросила, заметил ли он шар. Мальчик кивнул и улыбнулся. Тогда Оля окончательно убедилась, что новая подпись подходит к её рисунку.", listOf("Как Оля сначала назвала рисунок?", "Почему подруге день показался весёлым?", "Что предложила учительница перед выбором подписи?", "Какое название Оля выбрала для выставки?")),
        ComprehensionStory("3_19", 3, "Чьи шаги длиннее", "На даче Антон и его младшая сестра помогали дедушке придумать место для длинной клумбы. Он попросил сравнить две дорожки возле дома. Антон измерил первую своими шагами, а сестра прошла вторую. У мальчика получилось двенадцать шагов, у девочки восемнадцать. Ребята решили, что вторая дорожка длиннее первой.\nДедушка попросил их пройти одну и ту же дорожку. Антон насчитал двенадцать шагов, а сестра больше. Мальчик посмотрел, как она ставит ноги, и понял причину: её шаги короче. Сравнивать две дорожки по таким записям нельзя. Ребята вернулись к дедушке и рассказали ему о своей ошибке.\nТеперь обе дорожки измерил Антон, стараясь идти одинаковым шагом. Получилось двенадцать и тринадцать шагов. Дедушка посмотрел на новые записи и выбрал вторую дорожку для клумбы. Сестра принесла блокнот и нарисовала рядом обе дорожки. Антон подписал результаты, а снизу добавил, кто считал шаги при повторном измерении.", listOf("Зачем дедушка попросил сравнить дорожки?", "Почему первые результаты нельзя было правильно сравнить?", "Как дети изменили повторное измерение?", "Насколько отличались результаты повторного измерения?")),
        ComprehensionStory("3_20", 3, "Подарок для тёти", "Надя сделала для тёти объёмную открытку. Когда открытку раскрывали, внутри поднимался бумажный цветок. Девочка положила подарок в конверт и попросила маму отправить его вместе с посылкой. Мама заметила, что между книгами цветок может помяться, и предложила придумать упаковку.\nНадя нашла коробку от карандашей, но открытка в неё не помещалась. Тогда мама принесла другую коробку, немного шире. Девочка застелила дно мягкой бумагой и положила открытку сверху. Чтобы тётя сразу поняла, как раскрывать подарок, Надя нарисовала на отдельном листочке две картинки: закрытую открытку и поднявшийся цветок.\nЧерез несколько дней тётя позвонила и поблагодарила за подарок. Она поставила открытку на свой рабочий стол. Особенно её обрадовал листочек с картинками: тётя сначала осторожно рассматривала сложенную бумагу и не решалась потянуть её за края. Надя попросила прислать фотографию цветка рядом с тётиными карандашами, чтобы увидеть подарок на новом месте.", listOf("Что происходило при раскрытии открытки?", "Почему мама предложила сделать упаковку?", "Для чего Надя нарисовала две картинки?", "Что Надя попросила прислать после звонка?")),
        ComprehensionStory("3_21", 3, "Продолжение сказки", "На уроке дети придумывали продолжение сказки о потерянной короне. Рома написал, что корону нашёл дракон и сразу вернул королю. Учительница спросила, зачем дракон это сделал. Мальчик пожал плечами: ему хотелось скорее закончить рассказ и нарисовать красивый замок с башнями на соседней странице.\nРома перечитал начало сказки. Там говорилось, что король помог дракону найти пропавшего брата. Теперь мальчик придумал причину: дракон помнил добрый поступок и хотел отблагодарить короля. Рома добавил разговор у ворот замка. В нём дракон объяснял, где увидел корону и почему прилетел именно сюда.\nКогда дети читали свои работы, одноклассники внимательно слушали Рому. Один спросил, встретился ли дракон со своим братом. Мальчик показал соответствующую строчку в начале сказки, а потом добавил брата на рисунок. Теперь возле замка летели два дракона. Рома оставил под картинкой несколько пустых строк для новой истории об их дальнейших приключениях.", listOf("Почему Рома сначала хотел скорее закончить рассказ?", "Как король раньше помог дракону?", "Почему в новом варианте дракон вернул корону?", "Что Рома изменил в рисунке после вопроса одноклассника?")),
        ComprehensionStory("3_22", 3, "Жребий для команды", "В классе собирали команды для викторины. Друзья Пети попросились к нему, и он обрадовался. Но несколько ребят остались без команды. Учительница предложила вытянуть карточки с одинаковыми рисунками. Петя достал карточку с кораблём и оказался рядом с Таней и Глебом, с которыми редко разговаривал.\nПервое задание касалось героев сказок. Таня быстро вспомнила нужные имена. Во втором требовалось продолжить числовой ряд, и ответ нашёл Глеб. Петя хорошо разбирался в загадках и помог с третьим заданием. Перед последним вопросом ребята уже обсуждали ответы вместе и слушали друг друга, сверяя догадки.\nИх команда заняла второе место. Петя сначала огорчился, что не получил приз, но Таня предложила придумать название для команды. Глеб нарисовал корабль на карточке, а Петя добавил три окна. После уроков друзья позвали его играть. Мальчик пригласил с собой Таню и Глеба, чтобы познакомить их со своей компанией.", listOf("Как учительница предложила распределить детей по командам?", "Какое задание помог решить Глеб?", "Что Петя добавил к кораблю на карточке?", "Что показывает приглашение Тани и Глеба играть?")),
        ComprehensionStory("3_23", 3, "Окошки календаря", "Катя решила сделать для дедушки календарь на следующий месяц. Она нарисовала сетку и вписала числа, а возле каждого воскресенья добавила маленькое солнце. Когда дедушка посмотрел подарок, оказалось, что некоторые даты стоят под неверными днями недели. Катя начала месяц с понедельника, не проверив готовый календарь.\nДевочка нашла нужную страницу в календаре на стене. Первый день месяца приходился на четверг. Катя оставила три начальных окошка пустыми и заново расставила числа. Затем дедушка предложил отметить день, когда они собирались идти на выставку игрушек. Теперь эта дата оказалась в правильном столбце.\nКатя украсила свободные окошки рисунками дедушкиных игрушек: юлы, деревянного коня и волчка. Календарь встал на полку возле телефона. Когда мама спросила, на какое число назначена выставка, дедушка сразу показал нужную клетку. Катя проверила свою работу ещё раз и улыбнулась: её подарок теперь помогал семье помнить о предстоящей прогулке.", listOf("Почему даты сначала стояли под неверными днями недели?", "На какой день недели приходилось начало месяца?", "Какое событие Катя отметила по просьбе дедушки?", "Как семья использовала готовый подарок?")),
        ComprehensionStory("3_24", 3, "Вывеска для кружка", "Кружок рисования переехал в другой кабинет. Варя вызвалась сделать вывеску и нарисовала большие кисти, цветные пятна и карандаши. Название кружка она написала маленькими буквами между рисунками. Вывеска получилась яркой, и девочка прикрепила её к двери нового кабинета перед занятием.\nНа перемене пришёл первоклассник и спросил, где теперь занимаются рисованием. Варя показала на дверь, но мальчик признался, что издалека видит только цветные пятна. Девочка отошла к другому концу коридора и посмотрела сама. Название действительно терялось среди крупных рисунков, хотя вблизи каждая буква была хорошо заметна.\nВаря сделала новую вывеску. Сначала написала название крупными тёмными буквами, а рисунки расположила по краям. Перед тем как повесить лист, она попросила знакомую прочитать его издалека. Знакомая сразу назвала кружок. Первую работу Варя оставила внутри кабинета над столом с красками. Там её рисунки было удобно рассматривать, сидя рядом во время занятия.", listOf("Почему кружку понадобилась новая вывеска?", "Что первоклассник видел на вывеске издалека?", "Как Варя изменила название на второй вывеске?", "Почему первая работа подошла для места над столом?")),
        ComprehensionStory("3_25", 3, "Две похожие тетради", "У Егора и Димы были одинаковые тетради с зелёной обложкой. После работы в паре мальчики торопились на перемену и случайно поменялись ими. Дома Егор открыл тетрадь и удивился чужому почерку. На первой странице стояло имя Димы, но эту надпись нельзя было увидеть снаружи.\nНа следующий день ребята вернули друг другу тетради. Дима предложил подписать обложки, а Егор придумал добавить небольшие рисунки. Он выбрал футбольный мяч, Дима нарисовал корабль. Учительница разрешила приклеить карточки в верхнем углу, где оставалось пустое место. Имена мальчики написали под рисунками крупными буквами.\nЧерез неделю класс выполнял работу в парах. В конце урока Дима собрал обе тетради со стола и сразу протянул Егору ту, на которой был мяч. Егор заметил, что теперь им даже не приходится раскрывать обложки. На тетрадь по русскому языку он тоже наклеил мяч, чтобы узнавать её среди других.", listOf("Почему мальчики случайно поменялись тетрадями?", "Как Егор понял дома, что тетрадь чужая?", "Какие рисунки выбрали Егор и Дима?", "Зачем Егор приготовил мяч для новой тетради?")),

        // ===== 4 КЛАСС =====
        ComprehensionStory("4_1", 4, "Чья идея лучше", "Четвёртый класс готовил выставку о своём городе. Кирилл предложил нарисовать большой план улиц, а Ася хотела собрать рассказы жителей. Оба считали свою идею самой важной. На перемене ребята долго спорили, но так и не договорились.\nУчительница попросила их объяснить, что посетитель узнает из каждого материала. Кирилл сказал, что план поможет найти старые здания. Ася ответила, что рассказы покажут, как в этих зданиях жили и работали люди. Тогда дети заметили: их идеи отвечают на разные вопросы и могут дополнить друг друга.\nОни разделили работу. Кирилл вместе с друзьями нарисовал план и оставил возле трёх домов место для небольших карточек. Ася записала рассказы соседей, выбрала короткие отрывки и подписала, кто поделился воспоминаниями. Карточки прикрепили к плану цветными нитями.\nНа выставке одна посетительница долго рассматривала дом у площади. Она узнала в рассказе мастерскую своего дедушки и показала детям старую фотографию. Теперь у класса появился ещё один материал. Кирилл и Ася решили, что удачная выставка получилась благодаря объединению двух идей, а не победе одной из них.", listOf("Какие две идеи предложили дети?", "Какой вопрос учительницы помог им договориться?", "Как на выставке соединили план и рассказы?", "Почему посетительница показала старую фотографию?", "Какова основная мысль рассказа?")),
        ComprehensionStory("4_2", 4, "Два стакана", "Лёша решил узнать, почему после дождя лужи постепенно исчезают. Он налил одинаковое количество воды в два одинаковых стакана и поставил их на подоконник. Один стакан накрыл блюдцем, второй оставил открытым. В тетради мальчик отметил начальный уровень воды и дату.\nКаждое утро Лёша проверял стаканы. Через несколько дней уровень воды в открытом стакане стал заметно ниже. В накрытом стакане воды убыло совсем немного. Мальчик сначала записал: «Блюдце не даёт воде исчезнуть». Но старшая сестра предложила подумать, куда могла попасть вода из открытого стакана.\nОни вспомнили слово «испарение». Вода переходит в воздух, хотя мы не видим этот переход так же ясно, как струю из крана. Блюдце мешало воздуху свободно обмениваться над стаканом, поэтому вода убывала медленнее. Лёша исправил запись и описал только то, что наблюдал.\nПотом он захотел сравнить широкий и узкий сосуды. Сестра напомнила: сначала нужно решить, какое условие они будут менять, а остальные постараться сохранить одинаковыми. Теперь Лёша понимал, что хороший опыт начинается с вопроса и аккуратных записей, а один результат помогает придумать следующий.", listOf("Что было одинаковым в первом опыте?", "Какое условие Лёша изменил?", "Где уровень воды понизился сильнее?", "Какое явление помогло объяснить результат?", "Зачем в следующем опыте сохранять остальные условия одинаковыми?")),
        ComprehensionStory("4_3", 4, "Проверенная новость", "В школьную газету принесли заметку о том, что старую липу во дворе собираются спилить. Редактор Маша сразу представила пустое место возле скамейки. Под деревом дети отдыхали после уроков, и новость казалась ей тревожной. Автор заметки сказал, что услышал разговор двух взрослых у ворот.\nМаша решила сначала уточнить сведения. Она поговорила с завхозом и узнала, что во дворе действительно будут работать специалисты. Но речь шла об осмотре деревьев и удалении сухих веток. Решения спилить липу никто не принимал. Затем редактор попросила автора заметки вспомнить точные слова разговора. Оказалось, взрослые обсуждали сухую ветку, а не всё дерево.\nРебята переписали заметку. Они указали, кто сообщил о предстоящих работах, и объяснили, что именно планируется. В конце добавили просьбу не подходить к ограждению, когда во дворе начнётся работа.\nПосле выпуска газеты Маша сохранила первый вариант в редакционной папке. Он напоминал ей, как легко тревожное предположение превращается в уверенное сообщение. Теперь перед публикацией новых заметок редактор всегда спрашивала, откуда получены сведения и можно ли их проверить.", listOf("Откуда автор первой заметки получил сведения?", "Какие работы действительно планировались?", "Что автор неправильно понял в разговоре?", "Почему Маша сохранила первую заметку?", "Какое правило можно вывести из этой истории?")),
        ComprehensionStory("4_4", 4, "Пауза на сцене", "Перед школьным спектаклем Даша знала свою роль лучше всех. Она могла произнести слова героини даже с закрытыми глазами. На последней репетиции девочка торопила остальных: ей хотелось поскорее услышать весь разговор без остановок. Только Никита, игравший путника, всё время медлил после её вопроса. Даша считала, что он плохо выучил текст, и предложила напомнить ему реплику.\nРуководитель кружка попросил детей повторить сцену. Теперь Даша должна была смотреть на партнёра, а не ждать очереди говорить. Никита остановился у нарисованной двери, снял шапку и оглядел комнату. Его герой впервые оказался в чужом доме. После небольшой паузы ответ прозвучал совсем иначе: осторожно, словно путник ещё решал, можно ли доверять хозяйке.\nДаша поняла, зачем Никита медлил. Она тоже перестала выпаливать вопрос и подвинула к гостю стул. На спектакле разговор стал похож на настоящую встречу. Когда зрители засмеялись над следующей шуткой, дети подождали, пока смех стихнет, и продолжили. Вечером Даша отметила в своём тексте две паузы, которых раньше там не было.", listOf("Почему Даша хотела напомнить Никите реплику?", "Что предложил руководитель кружка?", "Почему путник отвечал после паузы?", "Как Даша изменила свою игру?", "Почему дети остановились после шутки?")),
        ComprehensionStory("4_5", 4, "Нижняя полка", "В библиотеке освободили небольшой стеллаж для книг, которые советовали сами читатели. Лиза вызвалась расставить их. Самые красивые обложки она поставила наверх, а потрёпанные книжки убрала на нижнюю полку. Получилась аккуратная выставка. Девочка даже повернула все корешки ровно и отошла к двери, чтобы посмотреть на свою работу издалека. Ей казалось, что теперь любой сразу найдёт интересное чтение.\nПосле уроков пришёл первоклассник с бабушкой. Он рассматривал нижнюю полку, но до яркой книги о кораблях наверху не мог дотянуться. Бабушка сняла её для него. Следом мальчик спросил, о чём остальные книги. Лиза заметила, что красивые обложки ничего не объясняют тому, кто ещё читает медленно. Подписи на корешках были мелкими, а некоторые названия совсем непонятными.\nНа следующий день девочка переставила детские книги ниже. Возле каждой положила карточку с крупной короткой подсказкой: приключение, смешной рассказ, история о животных. Наверху осталось чтение для старших. Через неделю Лиза увидела на пустом месте записку: книга о кораблях взята домой. Рядом лежал рисунок первоклассника с огромным синим парусом.", listOf("По какому признаку Лиза сначала расставила книги?", "Что мешало первокласснику выбрать книгу?", "Зачем Лиза сделала карточки?", "Какие книги девочка переставила ниже?", "Как Лиза узнала, что книгу о кораблях взяли?")),
        ComprehensionStory("4_6", 4, "После поворота", "На тренировке школьной команды Егор всегда начинал бег первым. Он быстро отрывался от друзей, но после поворота замедлялся, а к финишу приходил последним. Мальчик сердился на короткую дорожку: ему казалось, что именно поворот мешает показать хорошее время. Учитель физкультуры предложил Егору посмотреть один забег со стороны и записать, когда меняется порядок бегунов.\nЕгор сел возле площадки с карандашом. Лена начала спокойно, хотя двое ребят сразу обогнали её. Перед поворотом она прибавила шаг, а на последнем отрезке вышла вперёд. Дорожка у всех была одинаковой. Учитель спросил Егора, сколько сил у него обычно остаётся к этому месту. Мальчик вспомнил тяжёлое дыхание и понял, что тратит слишком много сил в самом начале.\nНа следующем занятии он попробовал бежать ровнее. Было трудно смотреть, как друзья уходят вперёд, и не ускоряться сразу. Зато после поворота Егор смог сохранить темп. Он ещё не победил Лену, но впервые добежал без остановки и улучшил своё время. В блокноте мальчик обвёл не место среди участников, а две цифры, показывающие его собственный результат.", listOf("Как Егор обычно начинал забег?", "Что мальчик сначала считал причиной неудачи?", "Что показал Егору забег Лены?", "Почему новый способ бега давался Егору трудно?", "Какой результат Егор отметил в блокноте?")),
        ComprehensionStory("4_7", 4, "Мера для теста", "Полина захотела записать бабушкин рецепт пирога в семейную тетрадь. Бабушка диктовала: немного муки, полная ложка сахара, молока столько, сколько возьмёт тесто. Девочка старательно выводила каждое слово, но потом остановилась. По такой записи она не смогла бы приготовить пирог сама. Бабушка удивилась: для неё все эти меры были понятны, ведь она пекла уже много лет.\nВ воскресенье они решили записать рецепт во время приготовления. Муку отмеряли одним стаканом, сахар — одной и той же ложкой. Полина отмечала количество и порядок действий. Когда бабушка сказала, что тесто уже хорошее, девочка попросила объяснить, как это узнать. Бабушка показала: оно мягкое, но не липнет к пальцам. Полина добавила эту подсказку рядом с количеством молока.\nЧерез неделю мама готовила пирог по новой записи. Она нашла нужный стакан, посмотрела заметку о тесте и почти не задавала вопросов. Бабушка попробовала кусочек и улыбнулась. Полина оставила в начале страницы старые слова про немного муки. Теперь они напоминали голос бабушки, а точные меры ниже помогали другому человеку повторить её работу.", listOf("Почему Полина остановилась, записывая рецепт?", "Когда они записали точное количество продуктов?", "Как бабушка определяла готовность теста?", "Кто первым приготовил пирог по новой записи?", "Зачем Полина сохранила старые слова в начале страницы?")),
        ComprehensionStory("4_8", 4, "Уголок неба", "После ужина семья собирала большой пазл с морским берегом. Папа выбрал детали домов, мама — лодки, а Роман взялся за небо. Почти все его кусочки были одинакового голубого цвета. Он прикладывал их друг к другу, но ничего не получалось. Когда остальные уже собрали половину картины, мальчик отодвинул свою кучку и сказал, что ему досталась самая бесполезная часть.\nМама предложила сначала найти детали с прямым краем. Роман разложил их по форме выступов и углублений. Среди голубых кусочков он заметил один с тонкой белой полоской. На рисунке коробки эта полоска оказалась верхушкой мачты. Мальчик присоединил кусочек к готовой лодке, и у его неба появилась точка, от которой можно было двигаться дальше. Теперь он сравнивал не только цвет.\nК вечеру в картине осталась небольшая пустота возле верхнего края. Роман сразу узнал нужную форму среди последних деталей. Он вставил кусочек и провёл ладонью над ровным небом. Папа хотел похвалить его за терпение, но мальчик уже разглядывал новую коробку. На этот раз он первым предложил выложить рамку.", listOf("Почему Роман решил, что ему досталась бесполезная часть?", "Какие детали мама посоветовала искать сначала?", "Чем оказалась белая полоска на голубом кусочке?", "Как этот кусочек помог продолжить работу?", "Что Роман предложил для следующего пазла?")),
        ComprehensionStory("4_9", 4, "Окно напротив", "На занятии по рисованию дети изображали дом напротив школы. Вера нарисовала одинаковые окна и ровные занавески. Работа выглядела аккуратно, но учитель предложил ещё раз взглянуть на настоящий дом. Девочка удивилась: она уже хорошо знала это здание и проходила мимо него каждое утро. Ей хотелось закончить рисунок раньше остальных и добавить красивую рамку по краю листа.\nВера подошла к окну класса. В одной квартире стоял цветок с длинными листьями, в другой виднелась стопка книг. На третьем этаже занавеска была отодвинута лишь наполовину. Девочка заметила и маленький бумажный самолёт возле стекла. Она вернулась к столу и изменила несколько окон. Дом сразу перестал походить на клетчатую тетрадь. Теперь казалось, что за каждым окном кто-то живёт.\nПосле занятия Вера показала рисунок маме. Та узнала окно соседки, которая любит выращивать цветы. Девочка не стала обводить лист рамкой: ей хотелось оставить место для дерева перед домом. На следующий день она заметила, что самолёт исчез, а возле книг появился зелёный шарф. Рисунок остался прежним, зато привычный дом продолжал меняться.", listOf("Как Вера сначала изобразила окна?", "Почему девочка не хотела снова смотреть на дом?", "Какие детали помогли сделать дом живым?", "Почему Вера отказалась от рамки?", "Что изменилось в окнах на следующий день?")),
        ComprehensionStory("4_10", 4, "Забытый конь", "В школьном шахматном кружке Арсений играл с младшей сестрой. Он давно изучал сложные задачи и ожидал лёгкой победы. Пока сестра обдумывала ход, мальчик рассказывал соседу о недавнем турнире. Затем быстро передвигал фигуру и снова отворачивался. Сестра молчала, внимательно смотрела на доску и вдруг забрала его ладью конём. Арсений возмутился: он совсем не заметил, когда конь оказался рядом.\nРуководитель кружка предложил им восстановить последние три хода. Сестра показала, как постепенно подвела фигуру к ладье. Каждый её ход был виден, но Арсений смотрел на собственный план и не проверял изменения на другой стороне доски. Он хотел сразу начать новую партию. Однако сначала записал неудачный ход в тетрадь и нарисовал положение фигур перед ошибкой.\nВо второй партии мальчик перестал разговаривать с соседом. Перед каждым ходом он спрашивал себя, что изменилось после хода сестры. Игра стала дольше, зато оба находили интересные продолжения. Когда кружок закрылся, партия ещё не закончилась. Дети зарисовали доску, чтобы продолжить дома. На рисунке Арсений особенно чётко отметил положение чужого коня.", listOf("Почему Арсений ожидал лёгкой победы?", "Какую фигуру сестра забрала конём?", "Почему Арсений пропустил угрозу?", "Что он делал перед ходами во второй партии?", "Зачем дети зарисовали доску?")),
        ComprehensionStory("4_11", 4, "Обычный конверт", "На экскурсии в маленьком музее Саша больше всего хотел увидеть старинные монеты. Но экскурсовод остановилась возле витрины с пожелтевшим конвертом. Мальчик разочаровался: похожие конверты лежали дома в ящике стола. Он даже шагнул к следующему стенду. Тогда экскурсовод прочитала начало письма, в котором человек спрашивал сестру, расцвела ли сирень у дома, и просил беречь его любимую чашку.\nПисьмо было написано во время долгой поездки. Его автор описывал новую работу и незнакомый город, но возвращался к обычным домашним вещам. Саша представил человека за столом, чашку с отколотой ручкой и куст возле крыльца. На фотографии рядом с письмом он заметил тот самый дом. Теперь старый конверт связывал изображение здания с голосом человека, который когда-то там жил.\nПосле экскурсии мальчик всё-таки посмотрел монеты, однако дома спросил маму о письмах в ящике. Среди них нашлась открытка от дедушки с рисунком поезда. Дедушка писал, что привезёт Саше маленький колокольчик. Мальчик вспомнил этот подарок и положил открытку рядом с ним. Раньше две вещи хранились в разных местах.", listOf("Что Саша сначала хотел увидеть в музее?", "Почему старый конверт его не заинтересовал?", "О каких домашних вещах писал автор письма?", "Что помогло Саше связать письмо с фотографией?", "Почему мальчик положил открытку рядом с колокольчиком?")),
        ComprehensionStory("4_12", 4, "Последний ответ", "На викторине команда Марины уверенно отвечала на вопросы о прочитанных книгах. Капитан слушала товарищей, но последнюю карточку заполнила сама: времени почти не оставалось. Нужно было назвать героя, который вернулся за потерянным письмом. Марина помнила эпизод и быстро написала имя. Тихий Федя попытался возразить, однако сигнал окончания уже прозвучал. Команда сдала карточку и стала ждать результатов.\nОтвет оказался неверным. Марина открыла книгу и увидела, что за письмом вернулся другой герой. Она хорошо помнила сцену, но перепутала имена. Федя как раз хотел сказать об этом. Капитан сначала сослалась на короткое время, потом признала: даже нескольких секунд хватило бы, чтобы услышать товарища. Ребята потеряли одно очко и заняли второе место вместо первого.\nПеред следующей игрой команда договорилась о простом порядке. Тот, кто заполняет карточку, сначала произносит ответ вслух. Остальные сразу подтверждают его или коротко объясняют сомнение. На тренировке Федя однажды тоже ошибся, и Марина помогла ему вспомнить нужный эпизод. Теперь последнее слово на карточке появлялось после общего решения. Старую ошибочную карточку капитан использовала как закладку в книге.", listOf("Почему Марина заполнила последнюю карточку сама?", "В чём состояла её ошибка?", "Что хотел сказать Федя?", "О каком порядке договорилась команда?", "Почему Марина стала помогать Феде на тренировке?")),
        ComprehensionStory("4_13", 4, "За краем фотографии", "Для семейного альбома Илья выбирал фотографию с летней прогулки. На одном снимке бабушка стояла у цветущего куста, но в углу виднелась рука папы с пакетом. Мальчик решил обрезать край: ему хотелось оставить только красивое. На другом снимке брат смешно щурился, и Илья отложил его совсем. Через час в папке лежали ровные, яркие фотографии, похожие на открытки.\nБабушка посмотрела подборку и спросила, куда делся снимок возле куста. Илья показал обрезанный вариант. Оказалось, в пакете папа нёс пирожки для всей семьи, а брат щурился потому, что рассказывал забавную историю против солнца. Эти подробности бабушка помнила именно благодаря неудачным деталям. Красивые кадры показывали место прогулки, но почти ничего не говорили о том, что происходило между людьми.\nИлья вернул две фотографии в альбом. Под первой написал, кто принёс обед, под второй — начало братовой истории. Он не отказался от аккуратных снимков: широкий вид парка тоже нашёл своё место. Когда приехал дядя, семья долго рассматривала именно страницу с пакетом. Дядя попросил записать рецепт пирожков на обороте, чтобы не забыть его.", listOf("Что Илья хотел убрать с фотографии у куста?", "Почему брат щурился на другом снимке?", "Что оказалось в папином пакете?", "Почему бабушке были важны неудачные детали?", "Что Илья добавил к возвращённым снимкам?")),
        ComprehensionStory("4_14", 4, "Широкая миска", "В кружке лепки Тимур задумал сделать высокую вазу для мамы. Он вытянул стенки из мягкой глины, но верхний край начал кривиться. Мальчик поддержал его ладонью, и ваза осела ещё сильнее. Рядом у других детей уже стояли готовые чашки. Тимур хотел смять свою работу и начать сначала, хотя до конца занятия оставалось совсем немного времени. Он сердито смотрел на низкий кривой сосуд.\nМастер попросил его описать, что получилось сейчас. У сосуда было широкое дно и невысокие стенки. Тимур признал, что это больше похоже на миску. Тогда он разгладил края и добавил по бокам два небольших выступа. Внутри нарисовал палочкой дорожку из листьев. Высокая ваза больше не получалась, зато новая форма оказалась устойчивой, а узор хорошо виден сверху.\nПосле обжига Тимур подарил миску маме. Она поставила её у входа и стала класть туда ключи. Вечером мальчик заметил, что папа тоже пользуется подарком и больше не ищет ключи по карманам разных курток. На следующем занятии Тимур снова задумал вазу, но сначала попросил мастера показать, как укрепляют её стенки.", listOf("Что Тимур задумал слепить сначала?", "Почему он хотел начать работу заново?", "Что помогло ему придумать новую форму?", "Как мама использовала подарок?", "О чём Тимур попросил мастера на следующем занятии?")),
        ComprehensionStory("4_15", 4, "Голос в коробке", "На день рождения дедушки Катя приготовила записанное поздравление. Родственники прислали ей короткие пожелания, и девочка соединила их в один рассказ. Свой голос она записывала несколько раз: ей не нравилось, что на слове поздравляю она запинается. Катя старалась говорить как ведущая по радио. Получалось ровно, но мама каждый раз говорила, что дочь будто читает чужое объявление, а не обращается к дедушке.\nДевочка отложила написанный текст и вспомнила, как летом они вместе чинили крышку старой коробки. Дедушка держал детали, а Катя выбирала цвет бумаги. Она рассказала об этом обычным голосом и добавила, что коробка до сих пор хранит её рисунки. В середине записи девочка засмеялась, вспомнив пятно клея на дедушкином рукаве. На этот раз она не стала перезаписывать поздравление.\nНа празднике дедушка слушал знакомые голоса и угадывал, кто заговорит следующим. Когда дошла очередь до Кати, он сразу посмотрел на неё и улыбнулся. После ужина дедушка попросил включить запись ещё раз. Девочка положила устройство рядом с той самой коробкой. На крышке сохранился маленький неровный угол, который они так и не смогли разгладить.", listOf("Почему Катя несколько раз записывала свой голос?", "Как мама оценивала такие записи?", "Какое общее дело Катя вспомнила?", "Почему девочка засмеялась в записи?", "Что в реакции дедушки показывает, что поздравление ему понравилось?")),
        ComprehensionStory("4_16", 4, "Правило для всех", "В дождливый день друзья играли дома в настольную игру о путешествиях. Антон первым дошёл до клетки с мостом и решил, что может сразу перейти на другой берег. В короткой памятке возле рисунка стояла стрелка. Через несколько ходов туда попала Соня, но Антон остановил её: по его мнению, теперь мост был занят. Девочка попросила найти такое правило в книжке из коробки.\nРебята прочитали весь раздел о переправах. Оказалось, стрелка показывала направление, а перед переходом нужно было взять карточку. Мост никто не мог занимать надолго. Друзья вспомнили, кто уже прошёл через него, и вернули свои фигурки на прежние клетки. Антон сначала предложил оставить его ход, ведь ошибка случилась давно. Соня заметила, что тогда одинаковое правило получится только для части игроков.\nОни решили начать этот круг заново и положили книжку открытой рядом с полем. Партия затянулась, зато споры о мосте закончились. Антон снова оказался первым возле переправы, взял карточку и пропустил ход, как она велела. Он вздохнул, но не стал искать исключение. За окном уже кончился дождь, а друзья попросили родителей подождать с прогулкой до конца игры.", listOf("Как Антон сначала понял стрелку возле моста?", "Зачем Соня попросила книжку с правилами?", "Что нужно было делать перед переходом?", "Почему Соня возразила против сохранения хода Антона?", "Как Антон поступил у моста во второй раз?")),
        ComprehensionStory("4_17", 4, "Стрелка у двери", "К школьному концерту четвёртый класс подготовил указатели для гостей. Миша написал на большом листе слово зал и нарисовал стрелку вправо. Он прикрепил лист возле входа, потому что отсюда сам всегда поворачивал к лестнице. После репетиции мальчик решил проверить указатель и попросил маму пройти по нему. Она повернула направо, но оказалась у закрытой двери в учительскую, а лестницу не заметила.\nМиша сначала подумал, что мама невнимательно смотрела. Потом встал у входа рядом с ней. С этого места большая стрелка была ближе к двери, чем к лестнице. Для человека, который впервые пришёл в школу, направление выглядело иначе. Мальчик перенёс лист к началу лестницы и добавил слова на второй этаж. Наверху он разместил ещё один указатель возле поворота коридора.\nВечером гости без остановок проходили к залу. Миша сидел у входа и только помогал пожилым людям снять верхнюю одежду. Одна женщина сказала, что впервые не пришлось спрашивать дорогу в незнакомой школе. После концерта мальчик снял указатели и оставил их в классе. На обороте первого листа он написал, откуда нужно смотреть, прежде чем рисовать стрелку.", listOf("Куда мама попала по первому указателю?", "Почему Миша сначала выбрал такое место для листа?", "Что мальчик заметил, встав рядом с мамой?", "Как он исправил указатели?", "Что показало, что новые указатели понятны гостям?")),
        ComprehensionStory("4_18", 4, "Карман для мелочи", "У Лены был тканевый пенал без отделений. Карандаши лежали вместе с ластиком, точилкой и маленькой линейкой. Перед уроком девочка долго искала нужную вещь и однажды рассыпала всё на парту. Мама предложила купить новый пенал, но Лене нравилась вышитая птица на старом. Она попросила помочь пришить внутри карман. Девочка представляла большой карман, в который поместится сразу вся мелочь и ничего не потеряется.\nМама дала ей бумагу для выкройки. Лена обвела ластик и точилку, добавила место по краям и вырезала прямоугольник. Они сначала прикололи бумажную деталь снаружи и посмотрели, сможет ли закрыться молния. Оказалось, большой карман перекрывает сгиб. Лена сделала два маленьких и разнесла их по разным сторонам. Мама пришила детали, а девочка выбрала нитки в цвет ткани.\nУтром Лена быстро достала ластик и не стала вытряхивать карандаши. Линейка осталась в общем отделении: для неё отдельный карман не требовался. На перемене подруга попросила нарисовать такую же выкройку. Лена согласилась, но сначала измерила её пенал. Он был короче, поэтому скопировать готовые размеры не получилось. Бумажные детали они примерили заново.", listOf("Почему Лена не захотела новый пенал?", "Зачем девочка сделала бумажную выкройку?", "Почему большой карман не подошёл?", "Какое решение выбрала Лена?", "Почему для подруги нельзя было скопировать размеры?")),
        ComprehensionStory("4_19", 4, "Место для чтения", "На даче Алёна устроила читальный уголок возле беседки. Она принесла лёгкий стул, положила на стол книги и нарисовала табличку с названием. Утром здесь было тихо, а листья закрывали стол от яркого солнца. Девочка пригласила двоюродного брата прийти после обеда. Ей хотелось показать, как красиво всё получилось. Она выбрала длинную сказку, которую они собирались читать по очереди до самого полдника.\nКогда брат пришёл, солнце освещало стол прямо, а ветер переворачивал страницы. Алёна удивилась: ещё утром уголок казался удобным. Брат предложил сесть с другой стороны беседки. Там было меньше света, зато книга не бликовала и листья почти не шевелились. Они перенесли стул и скамейку, а книги сложили в корзину. Табличка осталась на старом месте, потому что её было видно с дорожки.\nНа следующий день Алёна проверила уголок утром и после обеда. Она заметила, что удобное место зависит от времени, и перестала раскладывать все книги заранее. Теперь в беседке стояла корзина, которую легко было перенести. В дождливый вечер дети взяли её в дом и дочитали сказку у окна. Брат добавил в корзину собственную книгу для следующей встречи.", listOf("Почему уголок понравился Алёне утром?", "Что мешало читать после обеда?", "Куда дети перенесли места для сидения?", "Зачем Алёна стала хранить книги в корзине?", "Где дети закончили сказку?")),
        ComprehensionStory("4_20", 4, "Тихий час для задачи", "Костя никак не мог закончить трудную задачу. В комнате сестра учила стихотворение вслух, а из кухни слышался разговор родителей. Мальчик сердился, что все мешают ему работать. Он попросил домашних замолчать, но через минуту сам достал телефон посмотреть сообщение. Потом вспомнил, что нужно заточить карандаш. Когда мама вернулась, тетрадь лежала открытой на той же странице, хотя дома уже стало тихо.\nМама предложила Косте назвать всё, что прерывало его работу. В списке оказались голоса, телефон, карандаш и желание проверить время. Мальчик подготовил нужные вещи, убрал телефон в другую комнату и договорился с сестрой о двадцати минутах тишины. Она согласилась читать стихотворение на кухне, если потом Костя поможет проверить, не пропускает ли она строки. Он снова перечитал условие задачи и нарисовал короткую схему.\nНа этот раз Костя заметил связь между двумя числами и закончил решение. До конца условленного времени оставалось несколько минут. Он проверил ответ, закрыл тетрадь и позвал сестру. Девочка начала стихотворение, а брат следил по книге. Один раз она пропустила целую строчку. Костя показал место и подождал, пока сестра повторит трудный отрывок.", listOf("Почему тишина сначала не помогла Косте?", "Что мама предложила перед второй попыткой?", "О чём Костя договорился с сестрой?", "Что помогло ему увидеть связь между числами?", "Как мальчик выполнил обещание сестре?")),
        ComprehensionStory("4_21", 4, "Две стороны плаща", "Для школьной постановки о временах года Настя шила с мамой плащ Осени. Снаружи они прикрепили жёлтые листья из ткани, а внутри оставили серую подкладку. Девочка собиралась кружиться на сцене, чтобы листья красиво разлетались. На репетиции выяснилось, что сразу после её весёлого танца начиналась сцена дождя. Переодеваться было некогда: Осень должна была оставаться перед зрителями и произнести несколько грустных строк.\nНастя пробовала говорить печально в ярком плаще, но переход выглядел резким. Руководитель предложил замедлить движения. Когда девочка подняла край плаща, зрителям стала видна серая подкладка. Мама заметила это и предложила сделать застёжку, позволяющую быстро повернуть плащ другой стороной. На следующей репетиции Настя после танца остановилась, повернула ткань и медленно раскрыла руки. За её спиной ребята подняли бумажные облака.\nНа спектакле перемена заняла всего несколько секунд. Жёлтые листья скрылись внутри, а серый плащ напомнил пасмурное небо. Настя спокойно произнесла строки о дожде. В конце сцены она снова показала один золотой лист у края. После выступления младший брат попросил примерить плащ и долго выбирал, какая сторона подходит к его придуманному лесу.", listOf("Как выглядел плащ снаружи и внутри?", "Почему Настя не могла переодеться перед сценой дождя?", "Как возникла идея поворачивать плащ?", "Что помогало показать пасмурную погоду?", "Что Настя показала в конце сцены?")),
        ComprehensionStory("4_22", 4, "Билет без поездки", "Виталик собирал билеты из семейных поездок. Каждый он приклеивал в альбом и подписывал город. Однажды папа принёс красивый билет на спектакль, который отменили. Мальчик обрадовался яркому рисунку и добавил его к остальным. Подпись он оставил пустой, потому что поездки не было. Через месяц Виталик показывал альбом другу и не смог объяснить, почему между двумя городами оказался театр, в котором он никогда не бывал.\nПапа напомнил тот вечер. Семья уже собралась выходить, когда получила сообщение об отмене. Вместо спектакля они дома устроили театр теней: подвесили простыню и показывали за ней картонных зверей. Виталик играл зайца, а папа озвучивал медведя. Мальчик вспомнил, как смешно дрожали медвежьи уши, потому что папа не мог перестать смеяться. Этот вечер вовсе не был пустым, хотя билет не использовали.\nВиталик подписал страницу иначе: домашний театр после отмены спектакля. Рядом вклеил маленький рисунок зайца. Теперь в альбоме появились не только названия городов, но и короткие истории. Друг попросил научить его делать тени. В следующий выходной они вырезали новые фигуры, а старый билет поставили у входа в комнату как приглашение на представление.", listOf("Почему Виталик сначала не подписал новый билет?", "Что семья сделала вместо посещения театра?", "Кого изображали Виталик и папа?", "Как мальчик подписал страницу позже?", "Какое новое назначение получил билет?")),
        ComprehensionStory("4_23", 4, "Не только слова", "В класс пришёл новый ученик Денис. На перемене ребята наперебой спрашивали, где он жил и какие игры любит. Мальчик отвечал коротко и смотрел на парту. Олег решил, что новичок не хочет дружить. Он отошёл к окну и стал собирать бумажную модель автобуса. Нужно было аккуратно сгибать детали и следить, чтобы колёса оказались на одной высоте.\nЧерез несколько минут Денис подошёл к Олегу и молча указал на перевёрнутую деталь. Олег посмотрел на рисунок и понял, что действительно ошибся. Он предложил новичку придержать кузов, пока приклеиваются края. Денис согласился. За работой выяснилось, что дома он тоже делает модели, а сегодня просто устал отвечать сразу многим людям. Олег дал ему выбрать цвет бумажных сидений и показал оставшиеся детали.\nК концу перемены автобус ещё не был готов. Ребята договорились закончить его после уроков в классе, где разрешила остаться учительница. Когда другие дети снова окружили Дениса, Олег рассказал про их модель. Теперь вопросы были конкретными: открываются ли двери, сколько будет мест. Денис поднял автобус и сам объяснил, почему среднюю дверь придётся сделать неподвижной. Олег впервые услышал его длинный ответ.", listOf("Почему Олег решил, что Денис не хочет дружить?", "Как Денис помог Олегу?", "Почему новичок сначала мало говорил?", "О чём ребята договорились к концу перемены?", "Почему Денис позднее отвечал подробнее?")),
        ComprehensionStory("4_24", 4, "Рисунок скамейки", "Женя рисовал в парке скамейку под клёном. Он хотел закончить быстро, пока отец читал рядом книгу. На листе уже появились спинка и две ножки, когда на скамейку села женщина с тяжёлой сумкой. Женя расстроился: теперь часть скамейки была закрыта. Он попросил отца сказать женщине, чтобы она пересела. Отец предложил подождать или выбрать другой предмет, потому что скамейка нужна людям для отдыха.\nМальчик стал наблюдать. Женщина поставила сумку рядом, расправила шарф и закрыла глаза. Через минуту на другой край присел пожилой мужчина. Между ними осталось свободное место. Женя начал новый рисунок: оставил видимые части скамейки, добавил сумку и две фигуры. Он не пытался подробно изображать лица. Важнее казались усталые плечи женщины и рука мужчины, спокойно лежащая на спинке.\nКогда женщина ушла, Женя мог вернуться к первой работе. Однако второй рисунок понравился ему больше. Скамейка на нём показывала, зачем она стоит в парке. Отец закрыл книгу, и они отправились домой. Возле выхода мальчик заметил пустую лавочку и на этот раз представил, кто может сесть на неё вечером. Дома он подписал рисунок одним словом: передышка.", listOf("Почему Женя расстроился, когда женщина села?", "Почему отец не стал просить женщину пересесть?", "Какие детали Женя добавил во второй рисунок?", "Почему ему больше понравилась вторая работа?", "Как мальчик подписал рисунок?")),
        ComprehensionStory("4_25", 4, "Письма по порядку", "Убирая шкаф с мамой, Соня нашла пачку писем от старшей сестры, которая училась в другом городе. Девочка захотела перечитать их по порядку, но на нескольких конвертах даты стёрлись. Она разложила письма по цвету бумаги: сначала белые, потом голубые. Однако рассказ получился странным. В одном письме сестра уже показывала свою комнату, а в следующем ещё собиралась переезжать и просила прислать фотографии семьи.\nСоня стала искать подсказки внутри писем. Сначала сестра писала, что ждёт ключи. Потом рассказывала, как расставила книги на полке. Ещё позже сообщала, что на стене появились присланные фотографии. Девочка переставила листы, ориентируясь на эти события. Один короткий рассказ о прогулке не помогал определить место письма. Мама вспомнила, что сестра прислала его вместе с открыткой к осеннему празднику, и нашла открытку в соседней коробке.\nТеперь письма сложились в историю первых месяцев сестры в новом городе. Соня пронумеровала конверты карандашом и перевязала пачку лентой. Вечером она написала письмо: рассказала о находке и спросила, остались ли фотографии на стене. Вместо обычного сообщения девочка выбрала бумагу. Ей захотелось, чтобы сестра тоже могла когда-нибудь разложить её письма на столе.", listOf("Почему Соня не могла сразу разложить письма по датам?", "Почему сортировка по цвету бумаги не подошла?", "Какие события помогли определить порядок?", "Как определили место письма о прогулке?", "Почему Соня выбрала бумажное письмо?"))
    )

    fun getStoriesByGrade(grade: Int): List<ComprehensionStory> {
        return stories.filter { it.grade == grade }
    }

    fun getRandomStory(grade: Int): ComprehensionStory? {
        val list = getStoriesByGrade(grade)
        if (list.isEmpty()) return null
        return list.random()
    }
}
